L22: import { join, resolve } from 'node:path';
L23: import { spawnSync } from 'node:child_process';
L24: import { fileURLToPath } from 'node:url';
L25: 
L26: const REPO = resolve(fileURLToPath(import.meta.url), '..', '..');
L27: const RESULTS = join(REPO, 'results');
L28: const WORKSPACES = join(RESULTS, 'workspaces');
L29: const SUITE = JSON.parse(readFileSync(join(REPO, 'evals', 'evals.json'), 'utf8'));
L30: 
L31: const flag = (n) => process.argv.includes('--' + n);
L32: const env = (n, d) => process.env[n] ?? d;
L33: 
L34: const RUNNER = env('RUNNER', 'claude');
L35: const TRIALS = Number(env('TRIALS', '1'));
L36: const BASELINE = env('BASELINE', '1') !== '0' && env('BASELINE', '1') !== 'false';
L37: const JUDGE = env('JUDGE', '0') === '1';
L38: const MIN_RESOLUTION = Number(env('MIN_RESOLUTION', '0.8'));
L39: const MIN_LIFT = env('MIN_LIFT', '') === '' ? null : Number(env('MIN_LIFT'));
L40: 
L41: const IDS = env('EVAL_IDS', '').split(',').map((s) => s.trim()).filter(Boolean).map(Number);
L42: const evals = SUITE.evals.filter((e) => (IDS.length ? IDS.includes(e.id) : true));
L43: 
L44: // 基线腿要把 skill 从发现路径里摘掉，所以每条 eval 建两个独立工作目录。
L45: function makeWorkspace(evalId, arm) {
L46:   const ws = join(WORKSPACES, 'eval-' + evalId + '-' + arm);
L47:   rmSync(ws, { recursive: true, force: true });
L48:   mkdirSync(ws, { recursive: true });
…
L53:   }
L54:   return ws;
L55: }
L56: 
L57: function mountSkill(ws, arm) {
L58:   const dir = RUNNER === 'codex' ? join(ws, '.agents', 'skills') : join(ws, '.claude', 'skills');
L59:   if (arm === 'with-skill') {
L60:     mkdirSync(join(dir, 'quill'), { recursive: true });
L61:     for (const item of ['SKILL.md', 'references', 'assets'])
L62:       cpSync(join(REPO, item), join(dir, 'quill', item), { recursive: true });
L63:   } else {
L64:     mkdirSync(dir, { recursive: true }); // 目录存在但没有 skill —— 基线就是「裸 agent」
L65:   }
L66: }
L67: 
L68: // CLI runner 会自动批准每一次工具调用，没有沙箱。只在 GitHub 的一次性 runner 上跑，
L69: // 而且工作目录里只放 fixture 和 skill —— 绝不指向有凭据的仓库。
L70: function agentCommand(prompt) {
L71:   return RUNNER === 'codex'
L72:     ? { cmd: 'codex', args: ['exec', '--json', '--skip-git-repo-check', '--ignore-user-config', '--ephemeral', prompt] }
L73:     : { cmd: 'claude', args: ['-p', prompt, '--output-format', 'stream-json', '--verbose', '--setting-sources', 'project'] };
L74: }
L75: 
L76: function runAgent(ws, prompt) {
L77:   const { cmd, args } = agentCommand(prompt);
L78:   const r = spawnSync(cmd, args, {
L79:     cwd: ws,
L80:     env: process.env,
L81:     encoding: 'utf8',
L82:     timeout: Number(env('AGENT_TIMEOUT_MS', '600000')),
L83:     maxBuffer: 64 * 1024 * 1024,
L84:   });
L85:   return { code: r.status, stdout: r.stdout ?? '', stderr: r.stderr ?? '', error: r.error ? String(r.error.message) : null };
L86: }
L87: 
L88: // 拍快照必须在 agent 动手**之前**。放在 verify() 里等于跑完之后给跑完之后拍快照，
L89: // 「用户草稿逐字节未变」就会拿跑完的状态跟自己比，永远为真 —— 这条承诺等于没验证。
L90: function snapshotWorkspace(ws) {
L91:   const snapshot = join(ws, '.quill-snapshot.json');
L92:   spawnSync(process.execPath, [join(REPO, 'evals', 'check-workspace.mjs'), '--workspace', ws, '--snapshot', snapshot], { encoding: 'utf8' });
L93:   return snapshot;
L94: }
