L1: #!/usr/bin/env node
L2: // unchanged 断言的回归测试 —— 这条断言守的是 Quill 最核心的承诺（用户草稿只读不写），
L3: // 它自己失灵过两次，所以它得有人盯着：
L4: //   1) 只遍历跑之后存在的文件 → 草稿被删掉也判「逐字节未变」（0.11.0 的真实漏洞）
L5: //   2) run.mjs 在 agent 跑完之后才拍快照 → 拿跑完的状态跟自己比，永远为真
L6: // 第二个由 run.mjs 的调用顺序保证，这里守第一个：删除 / 改动 / 新增 / 空匹配都要被判出来。
L7: //
L8: // 用法：node evals/selftest-unchanged.mjs   （零依赖，退出码 0 = 断言行为正确）
L9: 
L10: import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, rmSync, unlinkSync } from 'node:fs';
L11: import { join, dirname } from 'node:path';
L12: import { tmpdir } from 'node:os';
L13: import { spawnSync } from 'node:child_process';
L14: import { fileURLToPath } from 'node:url';
L15: 
L16: const HERE = fileURLToPath(import.meta.url);
L17: const CHECKER = join(dirname(HERE), 'check-workspace.mjs');
L18: 
L19: const PATTERN = '40-Writing/**/我的文章.md';
L20: const DRAFT = '40-Writing/2026-09-20-remote-work/我的文章.md';
L21: 
L22: // 临时工作目录 + 一份只含 unchanged 断言的合成用例
L23: const root = mkdtempSync(join(tmpdir(), 'quill-selftest-'));
L24: const suitePath = join(root, 'suite.json');
L25: writeFileSync(suitePath, JSON.stringify({
L26:   evals: [{
L27:     id: 999, prompt: 'selftest', expected_output: 'unchanged 断言行为正确',
L28:     checks: [{ id: 'protected', kind: 'unchanged', patterns: [PATTERN] }],
L29:   }],
L30: }));
L31: 
L32: const ws = join(root, 'ws');
L33: const snapshotPath = join(root, 'before.json');
L34: 
L35: function seed(files) {
L36:   rmSync(ws, { recursive: true, force: true });
L37:   mkdirSync(ws, { recursive: true });
L38:   for (const [rel, body] of Object.entries(files)) {
L39:     mkdirSync(dirname(join(ws, rel)), { recursive: true });
L40:     writeFileSync(join(ws, rel), body);
L41:   }
L42: }
L43: 
L44: function snapshot() {
L45:   const r = spawnSync(process.execPath, [CHECKER, '--workspace', ws, '--snapshot', snapshotPath], { encoding: 'utf8' });
L46:   if (r.status !== 0) throw new Error('拍快照失败：' + r.stdout + r.stderr);
L47: }
L48: 
L49: function judge() {
L50:   const r = spawnSync(process.execPath, [CHECKER, '--eval', '999', '--workspace', ws, '--snapshot', snapshotPath, '--evals', suitePath], { encoding: 'utf8' });
L51:   return { pass: r.status === 0, out: r.stdout + r.stderr };
L52: }
L53: 
L54: const cases = [];
L55: const record = (name, ok, detail) => cases.push({ name, ok, detail });
L56: 
L57: // ① 原样不动 → 必须通过
L58: seed({ [DRAFT]: '初稿正文\n', 'notes/其他.md': '不相干\n' });
L59: snapshot();
L60: {
L61:   const r = judge();
L62:   record('原样不动 → 通过', r.pass, r.out.trim().split('\n').pop());
L63: }
L64: 
L65: // ② 改动一个字节 → 必须失败
L66: seed({ [DRAFT]: '初稿正文\n' });
L67: snapshot();
L68: writeFileSync(join(ws, DRAFT), '初稿正文改了一个字\n');
L69: {
L70:   const r = judge();
